function U.now()
return os.clock()
end
function U.json(ub)
local vb,wb=pcall(J.JSONEncode,J,ub)
return vb and wb or bYd[1813]
end
function U.unjson(xb)
local yb,zb=pcall(J.JSONDecode,J,xb)
return yb and zb or nil
end
function U.readJson(Ab)
local Bb,Cb=pcall(function()
return isfile(Ab)and readfile(Ab)or nil
end)
return Bb and Cb and U.unjson(Cb)or nil
end
function U.writeJson(Db,Eb)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
end)
pcall(writefile,Db,U.json(Eb))
end
function U.fmt(Fb)
Fb=tonumber(Fb)or 0
if Fb>=1e6 then
return string.format(bYd[1814],Fb/1e6)
end
if Fb>=1e4 then
return string.format(bYd[1815],Fb/1e3)
end
return tostring(math.floor(Fb+0.5))
end
function U.clamp(Gb,Hb,Ib)
return math.max(Hb,math.min(Ib,Gb))
end
function U.count(Jb)
local Kb=0
for Lb in pairs(Jb or{})do
Kb=Kb+1
end
return Kb
end
function U.list(Mb)
if type(Mb)~=bYd[1816]then
return{}
end
if#Mb>0 then
return Mb
end
local Nb={}
for Ob in pairs(Mb)do
table.insert(Nb,Ob)
end
table.sort(Nb,function(Pb,Qb)
return(tonumber(Pb)or 0)<(tonumber(Qb)or 0)
end)
local Rb={}
for Sb,Tb in ipairs(Nb)do
table.insert(Rb,Mb[Tb])
end
return Rb
end
function U.flat(Ub)
return Vector3 .new(Ub.X,0,Ub.Z)
end
function U.plain(Vb,Wb)
local Xb=type(Vb)
if Xb==bYd[1817]or Xb==bYd[726]or Xb==bYd[1818]then
return Vb
end
if Xb~=bYd[1816]or(Wb or 0)>6 then
return nil
end
local Yb={}
for Zb,_b in pairs(Vb)do
if type(Zb)==bYd[1817]or type(Zb)==bYd[726]then
Yb[Zb]=U.plain(_b,(Wb or 0)+1)
end
end
return Yb
end
function F.log(cc,dc,ec)
if cc>(O.logLevel or 1)then
return
end
local fc=string.format(bYd[1819],os.date(bYd[1820]),dc,tostring(ec))
table.insert(R.lines,fc)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,fc)
local gc=tostring(ec):lower()
if gc:find(bYd[1821])or gc:find(bYd[1822])or gc:find(bYd[1823])or dc==bYd[1824]then
R.problems=R.problems or{}
table.insert(R.problems,fc)
if#R.problems>30 then
table.remove(R.problems,1)
end
end
if O.logConsole then
print(bYd[1825]..fc)
