F.log(1,bYd[2182],string.format(bYd[2188],V.name(Xj.id)))
return false
end
local Hk=V.name(nk._stats.id.Value)
local Ik,Jk=F.request(bYd[1989],bYd[2189],nk)
if Ik and Jk then
table.insert(bb.actions,bYd[2190]..Hk..bYd[2191])
F.log(1,bYd[2182],string.format(bYd[2192],V.name(Xj.id),Hk,rk or 0,U.fmt(pk or 0),V.name(Xj.id)))
return true
end
F.log(1,bYd[2182],string.format(bYd[2193],V.name(Xj.id),Hk,tostring(Jk)))
return false
end
function ob.nearCast(Kk,Lk,Mk)
local Nk=0
for Ok,Pk in ipairs(Mk or{})do
for Qk,Rk in ipairs(Kk.casts)do
if Rk.id==Lk and Pk>=Rk.t-0.5 and Pk<=Rk.t+10 then
Nk=Nk+1
break
end
end
end
return Nk
end
function ob.watchIds()
local Sk,Tk={},0
if P.trial and P.trial.study and bb.trialId then
Sk[bb.trialId]=true
Tk=Tk+1
end
if O.pasWatch~=false then
for Uk,Vk in ipairs(bb.team or{})do
if not Sk[Vk.id]then
local Wk,Xk=pcall(ob.guess,Vk.id)
for Yk,Zk in ipairs(Wk and type(Xk)==bYd[1816]and Xk or{})do
if Zk.playable and not Zk.hand and ob.sure(Vk.id,Zk)~=bYd[2171]then
Sk[Vk.id]=true
Tk=Tk+1
break
end
end
end
end
end
return Sk,Tk
end
function ob.newWatch()
local _k,al=ob.watchIds()
return{t0=U.now(),ids=_k,n=al,idsAt=U.now(),copies={},placed={},removed={},transforms={},own={},foe=setmetatable({},{__mode=bYd[2194]}),foeBuffs={},meters={},steps={},deaths={},sumOf=setmetatable({},{__mode=bYd[2194]}),summons={},casts={},castN={},sales=0,firstPlaced={},nearN=0}
end
function ob.tick()
local bl=bb.pas
if not bl then
bl=ob.newWatch()
bb.pas=bl
end
if U.now()-bl.idsAt>30 then
bl.ids,bl.n=ob.watchIds()
bl.idsAt=U.now()
end
if(bl.n or 0)==0 then
return
end
if not bl.planned then
local cl,dl=pcall(ob.plan,bl)
if not cl then
bl.planned=true
F.log(1,bYd[2195],bYd[2196]..tostring(dl))
end
end
local el=U.now()-bl.t0
local fl={}
local gl={}
for hl,il in ipairs(bb.mine or{})do
local jl=il:FindFirstChild(bYd[1878])
local kl=jl and jl:FindFirstChild(bYd[2186])
if kl then
local ll=kl.Value
fl[il]=true
local ml=bl.copies[il]
local nl=jl:FindFirstChild(bYd[1906])
local ol=nl and tonumber(nl.Value)or 0
if not ml then
ml={id=ll,at=el,lvl=ol,sold=bl.sales,buff={},stat={}}
bl.copies[il]=ml
if#bl.placed<200 then
table.insert(bl.placed,{t=el,id=ll,sold=bl.sales})
end
if bl.firstPlaced[ll]==nil then
bl.firstPlaced[ll]=el
end
local pl=bb.pasExp
if type(pl)==bYd[1816]and pl.kind==bYd[1989]and ll~=pl.id and bl.sales>0 and not V.isFarm(ll)then
pl.otherDone=true
end
end
if ml.id~=ll then
if#bl.transforms<20 then
table.insert(bl.transforms,{t=el,from=ml.id,to=ll})
end
ml.id=ll
end
ml.lvl=math.max(ml.lvl,ol)
local ql=jl:FindFirstChild(bYd[2197])
ml.max=ql and tonumber(ql.Value)or ml.max
local rl=il:FindFirstChild(bYd[2198])
for sl,tl in ipairs(rl and rl:GetChildren()or{})do
local ul=(tl:IsA(bYd[2199])and tonumber(tl.Value))or 1
local vl=tl.Name
ml.buff[vl]=math.max(ml.buff[vl]or-math.huge,ul)
if ul>0 then
local wl=bl.own[vl]
if not wl then
wl={first=el,last=el,max=ul,by={},vals={},starts={}}
bl.own[vl]=wl
end
wl.last,wl.max=el,math.max(wl.max,ul)
wl.by[ll]=(wl.by[ll]or 0)+1
gl[vl]=(gl[vl]or 0)+1
if#wl.vals<12 then
local xl=math.floor(ul*1000+0.5)/1000
local yl=false
for zl,Al in ipairs(wl.vals)do
if Al==xl then
yl=true
break
end
end
if not yl then
table.insert(wl.vals,xl)
end
end
end
end
if bl.ids[ll]then
local Bl=jl:FindFirstChild(bYd[2200])
ml.tk=Bl and tonumber(Bl.Value)or ml.tk
local Cl=jl:FindFirstChild(bYd[2060])
ml.range=Cl and tonumber(Cl.Value)or ml.range
local Dl,El=pcall(function()
return il:GetPivot().Position
end)
if Dl then
ml.pos=El
end
local Fl=0
for Gl,Hl in ipairs(jl:GetChildren())do
if Hl:IsA(bYd[2201])or Hl:IsA(bYd[2202])then
local Il=Hl.Name
if not ob.STAT_SKIP[Il]then
local Jl=tonumber(Hl.Value)
local Kl=ml.stat[Il]
if Jl and(Kl or Fl<24)then
if not Kl then
Kl={lo=Jl,hi=Jl}
ml.stat[Il]=Kl
Fl=Fl+1
end
Kl.lo,Kl.hi=math.min(Kl.lo,Jl),math.max(Kl.hi,Jl)
end
end
end
end
end
end
end
for Ll,Ml in pairs(gl)do
local Nl=bl.own[Ll]
if Nl and(bl.ownCnt and(bl.ownCnt[Ll]or 0)or 0)==0 and#Nl.starts<40 then
table.insert(Nl.starts,el)
end
end
bl.ownCnt=gl
for Ol,Pl in pairs(bl.copies)do
if not fl[Ol]and not Pl.gone then
Pl.gone=el
local Ql=Pl.max~=nil and Pl.lvl>=Pl.max
if#bl.removed<100 then
table.insert(bl.removed,{t=el,id=Pl.id,lvl=Pl.lvl,atMax=Ql or nil})
end
if Ql and bl.ids[Pl.id]then
bl.sales=bl.sales+1
bl.lastSale=el
end
end
end
local Rl=bb.pasExp
if type(Rl)==bYd[1816]and Rl.kind==bYd[1989]and not Rl.otherDone and not Rl.freed and bb.reinc and(bb.reinc.sold or 0)>0 and U.now()-(tonumber(bb.reinc.soldAt)or 0)>20 then
local Sl,Tl=pcall(ob.freeSlot,Rl)
if not Sl then
Rl.freed=true
F.log(1,bYd[2195],bYd[2203]..tostring(Tl))
end
end
local Ul={}
for Vl,Wl in pairs(bl.copies)do
if not Wl.gone and bl.ids[Wl.id]and Wl.pos and Wl.range then
table.insert(Ul,Wl)
end
end
local Xl,Yl={},0
for Zl,am in ipairs(bb.enemies or{})do
local bm=am.m
if bm and am.pos then
Xl[bm]=true
local cm=false
local dm=U.flat(am.pos)
for em,fm in ipairs(Ul)do
if(dm-U.flat(fm.pos)).Magnitude<=fm.range+3 then
cm=true
break
end
end
local hm=bl.foe[bm]
if cm or hm then
local im=bm:FindFirstChildOfClass(bYd[2204])
local jm=math.max(1,(im and im.MaxHealth)or am.hp or 1)
if not hm then
hm={hp=am.hp,on={},met={},speed0=im and im.WalkSpeed or nil,boss=am.boss or nil}
bl.foe[bm]=hm
bl.nearN=bl.nearN+1
end
Yl=Yl+1
if Yl<=ob.ENEMY_MAX then
local km=bm:FindFirstChild(bYd[1878])
local lm={}
for nm,om in ipairs(km and km:GetChildren()or{})do
if om.Name:sub(1,8)==bYd[2205]and om:IsA(bYd[2199])and tonumber(om.Value)then
lm[om.Name]=tonumber(om.Value)/jm
end
end
local qm=((hm.hp or am.hp)-am.hp)/jm
if qm>=0.08 and#bl.steps<300 then
local rm
for um,vm in pairs(hm.met)do
if vm>0.02 and(lm[um]or 0)<vm*0.3 then
rm=rm or{}
rm[um]=vm
end
end
table.insert(bl.steps,{t=el,before=(hm.hp or am.hp)/jm,drop=qm,boss=am.boss or nil,reset=rm})
end
for wm,xm in pairs(lm)do
local ym=bl.meters[wm]or{max=0,n=0}
ym.max,ym.n=math.max(ym.max,xm),ym.n+1
bl.meters[wm]=ym
end
hm.met=lm
local zm=bm:FindFirstChild(bYd[2198])
local Am={}
for Bm,Cm in ipairs(zm and zm:GetChildren()or{})do
local Dm=(Cm:IsA(bYd[2199])and tonumber(Cm.Value))or 1
if Dm~=0 then
Am[Cm.Name]=Dm
end
end
for Em,Fm in pairs(Am)do
local Gm=bl.foeBuffs[Em]
if not Gm then
Gm={first=el,last=el,n=0,foes=0,near=0,boss=0,max=Fm,durs={},sp=0,spN=0,onsets={}}
bl.foeBuffs[Em]=Gm
end
Gm.n,Gm.last,Gm.max=Gm.n+1,el,math.max(Gm.max,Fm)
if cm then
Gm.near=Gm.near+1
end
if hm.boss then
Gm.boss=Gm.boss+1
end
if not hm.on[Em]then
hm.on[Em]=el
Gm.foes=Gm.foes+1
if#Gm.onsets<200 then
table.insert(Gm.onsets,el)
end
end
if im and(hm.speed0 or 0)>0 then
Gm.sp,Gm.spN=Gm.sp+im.WalkSpeed/hm.speed0,Gm.spN+1
end
end
for Hm,Im in pairs(hm.on)do
if not Am[Hm]then
local Jm=bl.foeBuffs[Hm]
if Jm and#Jm.durs<80 then
table.insert(Jm.durs,el-Im)
end
hm.on[Hm]=nil
end
end
end
hm.hp=am.hp
hm.frac=(am.hp or 0)/jm
end
end
end
for Km,Lm in pairs(bl.foe)do
if not Xl[Km]then
if#bl.deaths<600 and Lm.frac then
table.insert(bl.deaths,{frac=Lm.frac,boss=Lm.boss})
end
bl.foe[Km]=nil
end
end
for Mm,Nm in pairs(bb.helperDealt or{})do
if Nm.owner and bl.ids[Nm.owner]then
local Om=bl.sumOf[Mm]
if not Om then
local Pm=0
for Qm,Rm in pairs(bl.copies)do
if Rm.id==Nm.owner and not Rm.gone then
Pm=Pm+(Rm.tk or 0)
end
end
Om={owner=Nm.owner,id=Nm.id,born=el,tk=Pm}
bl.sumOf[Mm]=Om
if#bl.summons<200 then
table.insert(bl.summons,Om)
end
end
if Mm.Parent then
Om.last=el
elseif not Om.died then
Om.died=el
end
end
end
for Sm in pairs(bl.ids)do
local Tm=bb.casts and tonumber(bb.casts[Sm])or 0
if Tm>(bl.castN[Sm]or 0)then
bl.castN[Sm]=Tm
if#bl.casts<100 then
table.insert(bl.casts,{t=el,id=Sm})
end
end
end
end
function ob.evidence(Um,Vm,Wm)
local Xm=type(Wm.nums)==bYd[1816]and Wm.nums or{}
local Ym=Um.firstPlaced[Vm]
if not Ym then
return{why=bYd[2206]}
end
local Zm={}
for _m,an in ipairs(Wm.buffs or{})do
Zm[an]=true
end
local function bn(cn)
if#cn==0 then
return nil
end
table.sort(cn)
return cn[math.ceil(#cn/2)]
end
if Wm.family==bYd[1989]then
if(Um.sales or 0)==0 then
return{why=bYd[2207]}
end
local dn,en
for gn in pairs(Um.own)do
local hn,jn,kn,ln,mn=0,0,0,0,0
for nn,pn in pairs(Um.copies)do
local qn=pn.buff[gn]or 0
if(pn.sold or 0)>0 then
if pn.id~=Vm then
ln=ln+1
end
if qn>0 then
if pn.id==Vm then
hn=hn+1
else
kn=kn+1
end
mn=math.max(mn,qn)
end
elseif qn>0 then
jn=jn+1
end
end
if hn>0 and jn==0 and(not en or hn>en)then
dn,en={name=gn,other=kn,otherAfter=ln,top=mn},hn
end
end
if not dn then
return{why=bYd[2208]}
end
local rn=(dn.other>0 and bYd[748])or(dn.otherAfter>0 and bYd[2209])or bYd[2210]
return{seen=true,buff=dn.name,who=rn,nums={stacks=(Um.sales>1 and dn.top>1)or nil,sales=Um.sales},why=string.format(bYd[2211],en,dn.name,rn==bYd[2209]and bYd[2212]or bYd[740])}
end
local un=Wm.trigger and tostring(Wm.trigger):find(bYd[2213],1,true)~=nil
local vn=0
for wn,xn in ipairs(Um.casts)do
if xn.id==Vm then
vn=vn+1
end
end
if un and vn==0 and(Wm.family==bYd[1990]or Wm.family==bYd[1987])then
return{why=bYd[2214]}
end
if Wm.family==bYd[1990]then
local yn,zn,An
for Bn,Cn in pairs(Um.own)do
if Cn.first>=Ym-1 and(Zm[Bn]or Cn.first<=Ym+5 or un)and(not un or ob.nearCast(Um,Vm,Cn.starts)>0)then
local Dn=0
for En,Fn in pairs(Cn.by)do
if En~=Vm then
Dn=Dn+Fn
end
end
if Dn>0 and(not yn or(Zm[Bn]and not An)or((Zm[Bn]or false)==(An or false)and Dn>zn))then
yn,zn,An=Bn,Dn,Zm[Bn]
end
end
end
if not yn then
return{why=bYd[2215]}
end
return{seen=true,buff=yn,why=string.format(bYd[2216],yn)}
end
if Wm.family==bYd[1987]then
local Gn,Hn
for In,Jn in pairs(Um.foeBuffs)do
if Jn.first>=Ym-1 and Jn.near>0 and(Zm[In]or Jn.near>=0.5*Jn.n)and(not un or ob.nearCast(Um,Vm,Jn.onsets)>0)then
local Kn=Jn.near+(Zm[In]and 1e6 or 0)+(un and ob.nearCast(Um,Vm,Jn.onsets)*1000 or 0)
if not Hn or Kn>Hn then
Gn,Hn=In,Kn
end
end
end
if not Gn then
return{why=bYd[2217]}
end
local Ln=Um.foeBuffs[Gn]
local Mn={}
if#Ln.durs>=3 then
Mn.secsSeen=math.floor(bn(Ln.durs)*10+0.5)/10
elseif Ln.foes>=5 then
Mn.keepSeen=true
end
if Ln.spN>=5 then
local Nn=Ln.sp/Ln.spN
if Nn<0.97 then
Mn.slowSeen=math.floor((1-Nn)*100+0.5)/100
end
end
if Xm.chance and(Um.nearN or 0)>0 then
Mn.chanceSeen=math.floor(math.min(1,Ln.foes/Um.nearN)*100+0.5)/100
end
Mn.bossToo=Ln.boss>0 or nil
return{seen=true,buff=Gn,nums=Mn,why=string.format(bYd[2218],Ln.foes,Gn)}
end
if Wm.family==bYd[2046]then
local On=(tonumber(Xm.below)or 0.25)+0.02
local Pn,Qn=0,0
for Rn,Sn in ipairs(Um.deaths)do
if not Sn.boss then
Qn=Qn+1
if Sn.frac>0.04 and Sn.frac<=On then
Pn=Pn+1
end
end
end
if Qn<10 then
return{why=bYd[2219]}
end
local Tn=Pn/Qn
if Tn<0.3 then
return{why=string.format(bYd[2220],math.floor(Tn*100))}
end
return{seen=true,nums={shareSeen=math.floor(Tn*100+0.5)/100},why=string.format(bYd[2221],Pn,Qn,math.floor(On*100))}
end
if Wm.family==bYd[1901]then
local Un={}
for Vn,Wn in ipairs(Um.summons)do
if Wn.owner==Vm then
table.insert(Un,Wn)
end
end
if#Un<2 then
return{why=bYd[2222]}
end
table.sort(Un,function(Xn,Yn)
return Xn.born<Yn.born
end)
local Zn,ao,bo={},{},{}
for co=2,#Un do
local eo=(Un[co].tk or 0)-(Un[co-1].tk or 0)
if eo>0 then
table.insert(Zn,eo)
end
end
for fo,ho in ipairs(Un)do
if ho.died then
table.insert(ao,ho.died-ho.born)
end
table.insert(bo,{ho.born,1})
table.insert(bo,{ho.died or ho.last or ho.born,-1})
end
table.sort(bo,function(io,jo)
return io[1]<jo[1]
end)
local ko,mo=0,0
for oo,po in ipairs(bo)do
ko=ko+po[2]
mo=math.max(mo,ko)
end
local qo=bn(ao)
return{seen=true,nums={everySeen=bn(Zn),lifeSeen=qo and math.floor(qo+0.5)or nil,capSeen=mo,made= #Un},why=string.format(bYd[2223],#Un)}
end
if Wm.family==bYd[1991]then
local ro,so
for uo,vo in pairs(Um.own)do
if(vo.by[Vm]or 0)>0 and vo.first>=Ym-1 and(not ro or(Zm[uo]and not Zm[ro]))then
ro,so=uo,vo
end
end
local wo
for xo,yo in ipairs(Um.transforms)do
if yo.from==Vm then
wo=yo.to
end
end
if not ro then
local zo,Ao,Bo
for Co,Do in pairs(Um.copies)do
if Do.id==Vm or(wo and Do.id==wo)then
for Eo,Fo in pairs(Do.stat or{})do
if Fo.hi>Fo.lo and(not zo or(Fo.hi-Fo.lo)>(Bo-Ao))then
zo,Ao,Bo=Eo,Fo.lo,Fo.hi
end
end
end
end
if not zo then
return{why=bYd[2224]}
end
return{seen=true,nums={stat=zo,loSeen=Ao,hiSeen=Bo,transformTo=wo},why=string.format(bYd[2225],zo,tostring(Ao),tostring(Bo))}
end
return{seen=true,buff=ro,nums={maxSeen=so.max,steps= #so.vals,transformTo=wo},why=string.format(bYd[2226],ro,tostring(so.max))}
end
if Wm.family==bYd[1988]then
local Go,Ho,Io={},{},nil
for Jo,Ko in ipairs(Um.steps)do
for Lo,Mo in pairs(Ko.reset or{})do
table.insert(Go,Mo)
table.insert(Ho,Ko.drop)
Io=Io or Lo
end
end
if#Go<3 then
return{why=bYd[2227]}
end
return{seen=true,nums={atSeen=bn(Go),hitSeen=bn(Ho),meter=Io},why=string.format(bYd[2228],#Go)}
end
if Wm.family==bYd[2093]then
return{why=bYd[2229]}
end
return{why=bYd[2230]}
end
function ob.learn(No)
local Oo={}
for Po in pairs(No.ids or{})do
local Qo,Ro=pcall(ob.guess,Po)
for So,To in ipairs(Qo and type(Ro)==bYd[1816]and Ro or{})do
if To.playable and not To.hand then
local Uo,Vo=pcall(ob.evidence,No,Po,To)
if Uo and type(Vo)==bYd[1816]and Vo.seen then
local Wo=type(P.pasBook[Po])==bYd[1816]and P.pasBook[Po]or{}
local Xo=type(Wo[To.pid])==bYd[1816]and Wo[To.pid]or nil
local Yo={}
for Zo,_o in pairs(To.nums or{})do
Yo[Zo]=_o
end
for ap,bp in pairs(Vo.nums or{})do
Yo[ap]=bp
end
local cp=Xo~=nil and Xo.family==To.family and(Xo.buff==nil or Vo.buff==nil or Xo.buff==Vo.buff)
Wo[To.pid]={family=To.family,name=To.name,nums=Yo,buff=Vo.buff or(Xo and Xo.buff),who=Vo.who or To.who,trigger=To.trigger,keyword=To.keyword,sure=(cp and(tonumber(Xo.runs)or 0)>=1)and bYd[2171]or bYd[2231],runs=(cp and(tonumber(Xo.runs)or 0)or 0)+1,at=os.time(),why=Vo.why}
P.pasBook[Po]=Wo
table.insert(Oo,{id=Po,g=To,e=Wo[To.pid]})
elseif Uo and type(Vo)==bYd[1816]then
table.insert(Oo,{id=Po,g=To,miss=Vo.why})
else
table.insert(Oo,{id=Po,g=To,miss=bYd[2232]..tostring(Vo)})
end
end
end
end
ob._model={}
return Oo
end
function ob.unexplained(dp,ep)
if not(dp and dp.firstPlaced and dp.firstPlaced[ep])then
return nil
end
local fp={}
for gp,ip in ipairs(dp.learned or{})do
if ip.id==ep and ip.e and ip.e.buff then
fp[ip.e.buff]=true
end
end
local jp={}
for kp,lp in pairs(dp.own)do
if(lp.by[ep]or 0)>0 and not fp[kp]then
table.insert(jp,{w=bYd[2233],b=kp,n=lp.by[ep],max=lp.max})
end
end
for mp,np in pairs(dp.foeBuffs)do
if np.near>0 and np.first>=dp.firstPlaced[ep]-1 and not fp[mp]then
table.insert(jp,{w=bYd[2234],b=mp,n=np.foes,max=np.max})
end
end
table.sort(jp,function(op,pp)
return op.n>pp.n
end)
local qp={}
for rp=1,math.min(6,#jp)do
qp[rp]=jp[rp]
end
return#qp>0 and qp or nil
end
function ob.finish()
local tp=bb.pas
if not(tp and(tp.n or 0)>0)then
return
end
local up=ob.learn(tp)
tp.learned=up
local vp=P.trial and P.trial.study
if vp and bb.trialId then
P.pasBook[bb.trialId]=type(P.pasBook[bb.trialId])==bYd[1816]and P.pasBook[bb.trialId]or{}
P.pasBook[bb.trialId]._tries=(tonumber(P.pasBook[bb.trialId]._tries)or 0)+1
end
for wp,yp in ipairs(up)do
if yp.e then
F.log(1,bYd[2182],string.format(bYd[2235],V.name(yp.id),yp.g.name,ob.words(ob.withBook(yp.id,yp.g)),ob.SURE_WORDS[yp.e.sure]or tostring(yp.e.sure),tostring(yp.e.why)))
elseif vp and yp.id==bb.trialId then
F.log(1,bYd[2182],string.format(bYd[2236],V.name(yp.id),yp.g.name,tostring(yp.miss)))
end
end
F.saveSoon()
end
