if V._resc[ts]then
return V._resc[ts]
end
local us=1
pcall(function()
local vs=V.rows(ts)
local ws=vs and vs.max and vs[vs.max]
if type(ws)==bYd[1816]and ws.atk then
local xs,ys=V.attackInfo(ws.atk,ws.range,true),V.attackInfo(ws.atk,ws.range)
local zs,As=xs.n*(1+xs.dot),ys.n*(1+ys.dot)
