function V.nudge(Bs)
local Cs=P.learn[Bs]
local Ds,Es=0,0
if Cs and Cs.n and Cs.n>=1 then
if(tonumber(Cs.v)or 0)<3 then
Cs.eff,Cs.v=(tonumber(Cs.eff)or 1)*V.effRescale(Bs),3
end
Ds,Es=math.log(math.max(0.01,tonumber(Cs.eff)or 1))*Cs.n,Cs.n
end
local Fs=db.hiveUnit(Bs)
if Fs then
local Gs,Hs
if(tonumber(Fs.matches3)or 0)>=5 and(tonumber(Fs.eff3)or 0)>0 then
Gs,Hs=tonumber(Fs.eff3),tonumber(Fs.matches3)
else
Gs,Hs=(tonumber(Fs.eff)or 1)*V.effRescale(Bs),tonumber(Fs.matches)or 5
end
Ds,Es=Ds+math.log(math.max(0.01,Gs))*Hs,Es+Hs
end
if Es<=0 then
return 1
end
local Is=math.exp(Ds/Es)
local Js=Es/(Es+30)
return U.clamp(math.max(0.01,Is)^(0.5+0.4*Js),0.8-0.3*Js,1.35+1.65*Js)
end
