function kb.weatherStrength(aA)
local bA=kb.fx(aA)
local cA=bA.dmg/bA.cd/bA.hp/bA.speed*(1+(bA.range-1)/2)
for dA,eA in pairs(bA.kinds)do
cA=cA*(1+bb.rogueShare(dA)*eA)
end
if bA.ice>0 then
local fA=bb.rogueShare(bYd[1951])
cA=cA*(fA+(1-fA)/(1-bA.ice+bA.ice/fb.modFactor(bYd[2336])))
end
if bA.fly>0 then
cA=cA*(1-bA.fly*0.5)
end
if bA.noCC then
cA=cA*0.95
end
if bA.shroud then
cA=cA*0.9
end
if bA.zap then
cA=cA*0.85
end
return cA/kb.weatherK(aA)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(gA)
local hA=gA and type(P.hunt)==bYd[1816]and type(P.hunt.wk)==bYd[1816]and P.hunt.wk[tostring(gA)]or nil
