function kb.weatherLearn()
if bb.withOthers or#game:GetService(bYd[719]):GetPlayers()>1 then
return
end
local iA=bb.huntWeather or kb.weatherNow()
local jA,kA=bb.pred,bb.calRun
if not iA or type(jA)~=bYd[1816]or type(kA)~=bYd[1816]then
return
end
local function lA(mA,nA)
return type(mA)==bYd[1816]and tonumber(mA[nA]or mA[tostring(nA)])or nil
end
local oA={}
for pA=2,bb.wave()do
local qA,rA=lA(kA.alive,pA),lA(jA.aliveAt,pA)
if qA and rA and qA>0 and rA>0 then
table.insert(oA,qA/rA)
end
end
if#oA<3 then
return
end
table.sort(oA)
local sA=oA[math.ceil(#oA/2)]
P.hunt.wk=type(P.hunt.wk)==bYd[1816]and P.hunt.wk or{}
local tA=P.hunt.wk[tostring(iA)]
local uA=math.min(kb.WEATHER_K_RUNS-1,type(tA)==bYd[1816]and tonumber(tA.n)or 0)
local vA=kb.weatherK(iA)
local wA=math.max(1,uA)
local xA=math.exp((wA*math.log(vA)+math.log(vA*sA))/(wA+1))
xA=U.clamp(xA,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(iA),old=tA}
P.hunt.wk[tostring(iA)]={k=xA,n=(type(tA)==bYd[1816]and tonumber(tA.n)or 0)+1,at=os.time()}
F.log(1,bYd[2337],string.format(bYd[2338],tostring(iA),sA,tostring(iA),xA,vA,P.hunt.wk[tostring(iA)].n))
end
