local jtb=htb>0 and _sb*(itb/htb-1)or(etb or 0)
local ktb=atb[btb+2]
if ktb and btb+1<atb.max and ktb.cd>0 and gtb.cd>0 and htb>0 then
local ltb=_sb*((ktb.damage/ktb.cd)/htb-1)
local mtb=ctb+ktb.cost*dtb
if ltb/mtb>jtb/ctb then
jtb=jtb+(ltb/mtb*ctb-jtb)*0.5
end
end
local ntb=(gtb.range or 0)>(ftb.range or 0)and(1+((gtb.range-ftb.range)/math.max(1,ftb.range)))or 1
