if not stb.farm and stb.gain>0 then
table.insert(qtb,stb)
end
end
table.sort(qtb,function(ttb,utb)
return ttb.gain/ttb.cost>utb.gain/utb.cost
end)
local vtb,wtb=0,0
for xtb,ytb in ipairs(qtb)do
if ptb<=0 then
break
end
wtb=ytb.gain/ytb.cost
local ztb=math.min(1,ptb/ytb.cost)
vtb=vtb+ytb.gain*ztb
ptb=ptb-ytb.cost*ztb
end
return vtb+math.max(0,ptb)*wtb*0.7
end
