fb.DMG_SOLVE_LO,fb.DMG_SOLVE_HI,fb.DMG_SOLVE_TRIES=0.1,3,6
function fb.dmgSolve(VDb,WDb,XDb,YDb,ZDb)
local function _Db(aEb)
local bEb=table.clone(VDb)
bEb.dmgMul,bEb._dk=aEb,nil
local cEb,dEb=pcall(fb.runRaw,bEb,WDb,XDb)
if not(cEb and type(dEb)==bYd[1816])then
return nil
end
if ZDb then
