local edc=ddc._stats
if not V.isFarm(edc.id.Value)and edc:FindFirstChild(bYd[2060])then
table.insert(bdc,{p=U.flat(ddc:GetPivot().Position),r=edc.range.Value*(V.SUMMONER[edc.id.Value]and V.SUMMONER[edc.id.Value].reach or 1),air=bb.canAir(ddc)})
