for hdc,idc in ipairs(bb.samples)do
if idc.prog>gdc then
local jdc=U.flat(idc.pos)
for kdc,ldc in ipairs(bdc)do
if(jdc-ldc.p).Magnitude<=ldc.r then
if idc.prog>fdc then
fdc=idc.prog
end
if ldc.air then
gdc=idc.prog
break
end
end
end
end
end
end
local mdc,ndc={},bb.laneCount
