for sdc,tdc in ipairs(bdc)do
if(rdc-tdc.p).Magnitude<=tdc.r then
local udc=tostring(qdc.lane)
odc[udc]=(odc[udc]or 0)+1
if qdc.prog>(mdc[udc]or 0)then
mdc[udc]=qdc.prog
end
break
end
end
end
local vdc,wdc={},0
