for Edc,Fdc in ipairs(adc)do
local Gdc=(bb.laneW and Fdc.lane)and(mdc[tostring(Fdc.lane)]or 0)or fdc
if Fdc.hp>0 and Fdc.prog>Gdc+0.02 and Fdc.prog>(Bdc or 0)then
Bdc,Ddc=Fdc.prog,bb.laneW and Fdc.lane or nil
end
if Fdc.hp>0 and Fdc.fly and Fdc.prog>gdc+0.02 then
Cdc=true
end
end
