local eqc,fqc=dqc.pos.X-Xpc.X,dqc.pos.Z-Xpc.Z
if eqc*eqc+fqc*fqc<=Tpc then
_pc=_pc+1
local gqc=math.min(49,math.floor(dqc.prog*50))
if gqc<25 then
Ypc=bit32 .bor(Ypc,bit32 .lshift(1,gqc))
else
Zpc=bit32 .bor(Zpc,bit32 .lshift(1,gqc-25))
end
if dqc.prog<=0.3 then
aqc=aqc+1
elseif dqc.prog>=0.7 then
bqc=bqc+1
end
end
end
if _pc>0 then
local hqc=Ypc..bYd[1942]..Zpc
local iqc=Upc[hqc]
if not iqc then
iqc={p=Xpc,lo=Ypc,hi=Zpc,n=_pc,early=aqc,late=bqc}
Upc[hqc]=iqc
table.insert(Vpc,iqc)
elseif _pc>iqc.n then
iqc.p,iqc.n,iqc.early,iqc.late=Xpc,_pc,aqc,bqc
end
end
if Wpc%40==0 then
task.wait()
end
end
local jqc={}
for kqc,lqc in ipairs(Vpc)do
local mqc=false
for nqc,oqc in ipairs(Vpc)do
if kqc~=nqc and oqc.n>=lqc.n and bit32 .band(lqc.lo,oqc.lo)==lqc.lo and bit32 .band(lqc.hi,oqc.hi)==lqc.hi and(oqc.lo~=lqc.lo or oqc.hi~=lqc.hi or oqc.n>lqc.n)then
mqc=true
break
end
end
if not mqc then
table.insert(jqc,lqc)
end
if kqc%40==0 then
task.wait()
end
end
local pqc,qqc={},{}
local function rqc(sqc)
if sqc and not qqc[sqc]then
qqc[sqc]=true
table.insert(pqc,sqc)
end
end
table.sort(jqc,function(tqc,uqc)
return tqc.n>uqc.n
end)
for vqc=1,math.min(bb.STUDY_K,#jqc)do
rqc(jqc[vqc].p)
end
table.sort(jqc,function(wqc,xqc)
return wqc.early>xqc.early
end)
rqc(jqc[1]and jqc[1].p)
rqc(jqc[2]and jqc[2].p)
table.sort(jqc,function(yqc,zqc)
return yqc.late>zqc.late
end)
rqc(jqc[1]and jqc[1].p)
rqc(jqc[2]and jqc[2].p)
local Aqc=0
for Bqc,Cqc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if Aqc>=bb.STUDY_SHARED then
break
end
local Dqc=false
for Eqc,Fqc in ipairs(type(Cqc.units)==bYd[1816]and Cqc.units or{})do
local Gqc=Fqc==Ppc.id and Spc or((bb.baseRange(Fqc)or 0)*Qpc)
if Fqc==Ppc.id or(Gqc>0 and math.abs(Gqc-Spc)<=0.3*Spc)then
Dqc=true
break
end
end
local Hqc=Dqc and tonumber(Cqc.x)and tonumber(Cqc.z)and bb.nearSpot(Ppc.spots,tonumber(Cqc.x),tonumber(Cqc.z))or nil
if Hqc and not qqc[Hqc]then
rqc(Hqc)
Aqc=Aqc+1
end
end
return pqc,#Vpc,#jqc,Aqc
end
function bb.studyRun(Iqc)
local Jqc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-Jqc<20)do
task.wait(1)
end
local function Kqc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and F.where==bYd[1887]
end
if not Kqc()then
return
end
local Lqc,Mqc,Nqc=Iqc.info,Iqc.team,Iqc.base
local Oqc=Lqc.timeLimit~=nil
local Pqc=Oqc and 1 or math.max(1,tonumber(Iqc.hard)or 1)
local Qqc={Pqc*0.95,Pqc*1.05}
local Rqc=bb.bookFor(Lqc)
local Sqc={key=Iqc.key,label=bb.label(),n=Rqc and tonumber(Rqc.n)or 0,run=0,timed=Oqc,kills=Lqc.killScore and true or nil,hp=Pqc,at=os.time()}
bb.study=Sqc
local Tqc,Uqc,Vqc,Wqc,Xqc={},0,0,0,0
for Yqc,Zqc in ipairs(Iqc.attackers)do
local _qc,arc,brc,crc=bb.studyMoves(Zqc,Iqc.scale)
Tqc[Zqc.id]=_qc
Uqc,Vqc,Wqc,Xqc=Uqc+ #(Zqc.spots or{}),Vqc+arc,Wqc+ #_qc,Xqc+crc
if not Kqc()then
return
end
end
Sqc.moves=Wqc
F.log(1,bYd[2547],string.format(bYd[3949],Sqc.label,Uqc,Vqc,Wqc,Xqc>0 and string.format(bYd[3950],Xqc)or bYd[740]))
local drc={}
local function erc(frc)
return{samples=bb.samples,cache=drc,spots=frc,style=Nqc.style,list=Nqc.list,hybridHill=Nqc.hybridHill}
end
local function grc(hrc)
local irc=0
for jrc,krc in pairs(hrc)do
local lrc=bb.spotRec(jrc,krc)
if lrc then
irc=irc+(tonumber(lrc.wins)or 0)*200-((tonumber(lrc.runs)or 0)-(tonumber(lrc.wins)or 0))*1500
end
end
return irc
end
local function mrc(nrc)
local orc,prc,qrc=0,0,0
for rrc,trc in ipairs(Qqc)do
local urc=os.clock()
local vrc=fb.runRaw(Lqc,Mqc,{hpMul=trc,layout=erc(nrc),bg=true})
orc,prc,qrc=orc+fb.objective(vrc),prc+(tonumber(vrc.kills)or 0),qrc+(tonumber(vrc.wave)or 0)
task.wait(math.clamp((os.clock()-urc)*3,0.25,Iqc.pauseMax or 1.5))
if not Kqc()then
return nil
end
end
Sqc.n,Sqc.run=Sqc.n+1,Sqc.run+1
return orc/ #Qqc*100+grc(nrc),prc/ #Qqc,qrc/ #Qqc
end
local function wrc(xrc)
local yrc={}
for zrc,Arc in pairs(xrc)do
yrc[zrc]=Arc
end
return yrc
end
local function Brc(Crc,Drc,Erc)
for Frc,Grc in pairs(Crc)do
if Frc~=Drc and(U.flat(Grc)-U.flat(Erc)).Magnitude<4.5 then
return true
end
end
return false
end
local Hrc={spots=wrc(Nqc.spots)}
Hrc.s,Hrc.kills,Hrc.wave=mrc(Hrc.spots)
if not Hrc.s then
return bb.studyEnd(Sqc,Iqc,nil)
end
Sqc.baseKills,Sqc.baseWave=Hrc.kills,Hrc.wave
Sqc.bestKills,Sqc.bestWave=Hrc.kills,Hrc.wave
if Rqc and Rqc.aside==nil then
local Irc,Jrc=wrc(Hrc.spots),0
for Krc,Lrc in ipairs(Iqc.attackers)do
local Mrc=Rqc.spots[Lrc.id]
local Nrc=type(Mrc)==bYd[1816]and tonumber(Mrc[1])and tonumber(Mrc[3])and bb.nearSpot(Lrc.spots,tonumber(Mrc[1]),tonumber(Mrc[3]))or nil
if Nrc and Nrc~=Irc[Lrc.id]and not Brc(Irc,Lrc.id,Nrc)then
Irc[Lrc.id]=Nrc
Jrc=Jrc+1
end
end
if Jrc>0 then
local Orc,Prc,Qrc=mrc(Irc)
if not Orc then
return bb.studyEnd(Sqc,Iqc,Hrc)
end
if Orc>Hrc.s then
Hrc={spots=Irc,s=Orc,kills=Prc,wave=Qrc}
Sqc.bestKills,Sqc.bestWave=Prc,Qrc
end
end
end
local Rrc,Src=U.now(),Sqc.run
local function Trc(Urc)
if not(Urc.s and Urc.s>Hrc.s+math.max(50,math.abs(Hrc.s)*0.005))then
return false
end
Hrc=Urc
Sqc.bestKills,Sqc.bestWave,Sqc.better=Urc.kills,Urc.wave,(Sqc.better or 0)+1
pcall(bb.bookSave,Lqc,Iqc,Hrc,Sqc)
return true
end
local function Vrc()
if Sqc.run-Src>=60 or U.now()-Rrc>240 then
Rrc,Src=U.now(),Sqc.run
F.log(1,bYd[2547],bb.studyWords(Sqc))
end
end
local Wrc={Hrc}
for Xrc,Yrc in ipairs(Iqc.attackers)do
local Zrc={}
for _rc,asc in ipairs(Wrc)do
table.insert(Zrc,asc)
for bsc,csc in ipairs(Tqc[Yrc.id]or{})do
if csc~=asc.spots[Yrc.id]and not Brc(asc.spots,Yrc.id,csc)then
local dsc=wrc(asc.spots)
dsc[Yrc.id]=csc
local esc,fsc,gsc=mrc(dsc)
if not esc then
return bb.studyEnd(Sqc,Iqc,Hrc)
end
local hsc={spots=dsc,s=esc,kills=fsc,wave=gsc}
table.insert(Zrc,hsc)
Trc(hsc)
Vrc()
end
end
end
table.sort(Zrc,function(isc,jsc)
return(isc.s or-1e18)>(jsc.s or-1e18)
end)
Wrc={}
for ksc=1,math.min(bb.STUDY_BEAM,#Zrc)do
table.insert(Wrc,Zrc[ksc])
end
end
local lsc={}
for msc,nsc in ipairs(Iqc.attackers)do
if Tqc[nsc.id]and#Tqc[nsc.id]>0 then
table.insert(lsc,nsc.id)
end
end
while Kqc()and#lsc>0 do
local osc=wrc(Hrc.spots)
for psc=1,math.min(2,#lsc)do
local qsc=lsc[math.random(#lsc)]
local rsc=Tqc[qsc]
local ssc=rsc[math.random(#rsc)]
if not Brc(osc,qsc,ssc)then
osc[qsc]=ssc
end
end
local tsc,usc,vsc=mrc(osc)
if not tsc then
break
end
Trc({spots=osc,s=tsc,kills=usc,wave=vsc})
Vrc()
end
bb.studyEnd(Sqc,Iqc,Hrc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(wsc,xsc)
local ysc=N.PC.raycast(wsc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not ysc then
return nil
end
if not N.PC.is_valid_raycast_hit(ysc.Instance,xsc)then
return nil
end
local zsc=ysc.Position
if bb.blockedSpot(zsc)then
return nil
end
local Asc=(tonumber(xsc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Asc*2,2.5,Asc*2)
bb.probe.CFrame=CFrame.new(zsc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return zsc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==bYd[2259]then
return
end
local Bsc=bb.info
local function Csc()
return not F.alive or bb.finished or bb.result or F.where~=bYd[1887]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local Dsc,Esc={},{}
for Fsc,Gsc in ipairs(bb.team or{})do
table.insert(Dsc,Gsc.u)
if not V.isFarm(Gsc.id)and not V.allyBuff(Gsc.id)and Gsc.uuid~=bb.trainee and V.rows(Gsc.id)then
local Hsc,Isc=pcall(V.score,Gsc.u,bb.mod)
table.insert(Esc,{e=Gsc,id=Gsc.id,sc=Hsc and Isc or 0})
end
end
if#Esc==0 then
return
end
table.sort(Esc,function(Jsc,Ksc)
return Jsc.sc>Ksc.sc
end)
local function Lsc()
local Msc,Nsc={},0
for Osc,Psc in ipairs(Esc)do
for Qsc,Rsc in ipairs(bb.mine or{})do
local Ssc=Rsc:FindFirstChild(bYd[1878])
local Tsc=Ssc and Ssc:FindFirstChild(bYd[2185])
if Tsc and Tsc.Value==Psc.e.uuid and Ssc:FindFirstChild(bYd[2186])and Ssc.id.Value==Psc.id then
Msc[Psc.id]=Rsc:GetPivot().Position
Nsc=Nsc+1
break
end
end
end
return Msc,Nsc
end
local Usc=U.now()
local Vsc,Wsc=Lsc()
while Wsc< #Esc and U.now()-Usc<bb.STUDY_INF_WAIT do
task.wait(5)
if Csc()then
return
end
Vsc,Wsc=Lsc()
end
if Wsc==0 or Csc()then
return
end
local Xsc={}
local function Ysc(Zsc)
local _sc=Zsc.hybrid_placement and not Zsc.hill_unit
local atc=_sc and bb.hybridHill
local btc=((Zsc.hill_unit or atc)and bYd[2573]or(_sc and bYd[3890])or bYd[3891])..bYd[1942]..tostring(Zsc.override_hitbox_radius or bYd[740])
if Xsc[btc]then
return Xsc[btc]
end
local ctc={}
local dtc=atc and bb.hillData(Zsc)or Zsc
for etc,ftc in ipairs(bb.cands or{})do
local gtc=bb.validOpen(ftc,dtc)
if gtc then
table.insert(ctc,gtc)
end
if etc%40==0 then
task.wait()
end
end
Xsc[btc]=ctc
return ctc
