local htc={info=Bsc,team=fb.teamFrom(Dsc,Bsc.map),key=bb.bookKey(Bsc),hard=1,scale=tonumber(Bsc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local itc={spots={},style=bYd[2722],hybridHill=bb.hybridHill and true or false}
for jtc,ktc in ipairs(Esc)do
