end
return string.format(bYd[3953],tostring(ptc.label),tonumber(ptc.n)or 0,tonumber(ptc.run)or 0,qtc(ptc.bestKills,ptc.bestWave),qtc(ptc.baseKills,ptc.baseWave),(ptc.better or 0)>0 and bYd[3954]or bYd[740])
