function bb.bookSave(ttc,utc,vtc,wtc)
P.mapBook=type(P.mapBook)==bYd[1816]and P.mapBook or{}
local xtc={}
for ytc,ztc in pairs(vtc.spots or{})do
xtc[ytc]={math.floor(ztc.X*10+0.5)/10,math.floor(ztc.Y*10+0.5)/10,math.floor(ztc.Z*10+0.5)/10}
end
P.mapBook[utc.key]={spots=xtc,style=utc.base.style,hp=wtc.hp,n=wtc.n,kills=vtc.kills and math.floor(vtc.kills+0.5)or nil,wave=vtc.wave and math.floor(vtc.wave*10+0.5)/10 or nil,base=wtc.baseWave and math.floor(wtc.baseWave*10+0.5)/10 or nil,label=wtc.label,map=ttc.map,killScore=wtc.kills,at=os.time()}
local Atc={}
for Btc,Ctc in pairs(P.mapBook)do
table.insert(Atc,{k=Btc,at=type(Ctc)==bYd[1816]and tonumber(Ctc.at)or 0})
end
if#Atc>bb.BOOK_MAX then
table.sort(Atc,function(Dtc,Etc)
return Dtc.at>Etc.at
end)
for Ftc=bb.BOOK_MAX+1,#Atc do
P.mapBook[Atc[Ftc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(Gtc,Htc,Itc)
