end
Gtc.ended=true
if Itc and Htc then
local Jtc=bb.bookFor(Htc.info)
if Jtc then
Jtc.n=Gtc.n
F.saveSoon()
elseif Gtc.run>0 then
pcall(bb.bookSave,Htc.info,Htc,Itc,Gtc)
end
end
if Gtc.run>0 then
F.log(1,bYd[2547],bb.studyWords(Gtc))
end
end
function bb.studyReport()
