bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3*24*3600,0.015,300
function bb.layoutRecFor(buc,cuc)
local duc=bb.bookKey(buc)
P.layoutRec=type(P.layoutRec)==bYd[1816]and P.layoutRec or{}
local euc=P.layoutRec[duc]
if type(euc)~=bYd[1816]then
if not cuc then
return nil
end
euc={at=os.time()}
P.layoutRec[duc]=euc
if U.count(P.layoutRec)>80 then
local fuc,guc
for huc,iuc in pairs(P.layoutRec)do
local juc=type(iuc)==bYd[1816]and tonumber(iuc.at)or 0
if not guc or juc<guc then
fuc,guc=huc,juc
end
end
P.layoutRec[fuc]=nil
end
end
return euc
end
function bb.layoutAdd(kuc,luc,muc,nuc,ouc)
kuc.runs,kuc.wins=(tonumber(kuc.runs)or 0)+1,(tonumber(kuc.wins)or 0)+(luc and 1 or 0)
kuc.sec,kuc.wave=type(kuc.sec)==bYd[1816]and kuc.sec or{},type(kuc.wave)==bYd[1816]and kuc.wave or{}
if luc and tonumber(muc)then
table.insert(kuc.sec,math.floor(muc+0.5))
end
table.insert(kuc.wave,tonumber(nuc)or 0)
if tonumber(ouc)then
kuc.kills=type(kuc.kills)==bYd[1816]and kuc.kills or{}
table.insert(kuc.kills,math.floor(tonumber(ouc)))
while#kuc.kills>bb.LAYOUT_KEEP do
table.remove(kuc.kills,1)
end
end
while#kuc.sec>bb.LAYOUT_KEEP do
table.remove(kuc.sec,1)
end
while#kuc.wave>bb.LAYOUT_KEEP do
table.remove(kuc.wave,1)
end
end
function bb.layoutJudge(puc,quc,ruc,suc)
local tuc,uuc=tonumber(puc and puc.runs)or 0,tonumber(quc and quc.runs)or 0
if tuc<1 or uuc<bb.LAYOUT_CONTROL then
return nil
end
if suc and type(puc.kills)==bYd[1816]and type(quc.kills)==bYd[1816]and#puc.kills>=1 and#quc.kills>=bb.LAYOUT_CONTROL then
local vuc,wuc=bb.labMedian(puc.kills),bb.labMedian(quc.kills)
if vuc and wuc and vuc<wuc*0.97 and(#puc.kills>=2 or vuc<wuc*0.85)then
return string.format(bYd[3960],vuc,wuc)
end
return nil
end
local xuc,yuc=(tonumber(puc.wins)or 0)/tuc,(tonumber(quc.wins)or 0)/uuc
if not ruc and yuc>=0.5 then
if xuc+0.25<yuc and(tuc>=2 or(xuc==0 and yuc>=0.9 and uuc>=3))then
return string.format(bYd[3961],tonumber(puc.wins)or 0,tuc,tuc==1 and bYd[740]or bYd[1664],tonumber(quc.wins)or 0,uuc)
end
local zuc,Auc=bb.labMedian(puc.sec),bb.labMedian(quc.sec)
if zuc and Auc and zuc>Auc*1.10 and(#puc.sec>=2 or zuc>Auc*1.25)then
return string.format(bYd[3962],math.floor(zuc/60),zuc%60,math.floor(Auc/60),Auc%60)
end
return nil
end
local Buc,Cuc=bb.labMedian(puc.wave),bb.labMedian(quc.wave)
if Buc and Cuc and Buc<Cuc-math.max(1,Cuc*0.03)and(tuc>=2 or Buc<Cuc*0.85)then
return string.format(bYd[3963],Buc,Cuc)
end
return nil
end
function bb.layoutResult(Duc,Euc)
local Fuc=bb.info
local Guc=bb.layoutSrc
if not(Fuc and Guc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not Fuc.timeLimit then
return
end
local Huc=bb.wave()
local Iuc=bb.layoutRecFor(Fuc,true)
Iuc.at=os.time()
local Juc=Fuc.timeLimit~=nil
local Kuc=Fuc.killScore and true or nil
local Luc=Kuc and(bb.killsEnd or bb.realKills())or nil
if Guc==bYd[3933]then
local Muc=bb.bookFor(Fuc)
if not Muc then
return
end
