for Xuc,Yuc in ipairs(bb.mine or{})do
local Zuc=Yuc._stats
local _uc=Zuc.id.Value
if Zuc:FindFirstChild(bYd[2060])and not V.isFarm(_uc)and not V.allyBuff(_uc)then
local avc,bvc=U.flat(Yuc:GetPivot().Position),Zuc.range.Value
if Suc(_uc)and not V.toggleOf(_uc)then
Vuc=Vuc+1
table.insert(Wuc,{p=avc,r=bvc})
else
for cvc,dvc in ipairs(bb.samples)do
if(U.flat(dvc.pos)-avc).Magnitude<=bvc then
Tuc,Uuc=math.min(Tuc,dvc.prog),math.max(Uuc,dvc.prog)
end
end
end
end
end
if Uuc<=Tuc then
Tuc,Uuc=0.75,0.98
end
local evc=(Ruc or Vuc)+1
local fvc=({Tuc,Uuc,(Tuc+Uuc)/2,Tuc-(Uuc-Tuc)/2})[evc]
if not fvc then
return nil
end
local gvc=V.range(Quc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local hvc={}
for ivc,jvc in ipairs(bb.cands)do
local kvc,lvc,mvc=U.flat(jvc),0,0
for nvc,ovc in ipairs(bb.samples)do
if(U.flat(ovc.pos)-kvc).Magnitude<=gvc then
mvc=mvc+1
if math.abs(ovc.prog-fvc)<=0.05 then
lvc=lvc+1
local pvc=U.flat(ovc.pos)
for qvc,rvc in ipairs(Wuc)do
if(pvc-rvc.p).Magnitude<=rvc.r then
lvc=lvc-0.5
break
end
end
end
end
end
if lvc>0 then
table.insert(hvc,{pos=jvc,sc=lvc,cov=mvc})
end
if ivc%60==0 then
task.wait()
end
end
table.sort(hvc,function(tvc,uvc)
return tvc.sc>uvc.sc
end)
for vvc,wvc in ipairs(hvc)do
local xvc=bb.valid(wvc.pos,Quc.data)
if xvc then
F.log(1,bYd[3892],string.format(bYd[3970],V.name(Quc.id),bb.CONTROL_WORDS[evc],math.floor(fvc*100+0.5)))
return xvc,wvc.cov,fvc
end
if vvc%20==0 then
task.wait()
end
end
return nil
end
