function bb.learn()
local zMc=bb.calRun and bb.calRun.potBy
if type(zMc)~=bYd[1816]then
return
end
pcall(bb.sampleHelpers,true)
local AMc={}
for BMc,CMc in pairs(bb.ownDealt or{})do
if not V.isFarm(CMc.id)then
AMc[CMc.id]=(AMc[CMc.id]or 0)+(tonumber(CMc.v)or 0)
end
end
for DMc,EMc in pairs(bb.helperDealt or{})do
if EMc.owner and V.SUMMONER[EMc.owner]then
AMc[EMc.owner]=(AMc[EMc.owner]or 0)+(tonumber(EMc.v)or 0)
end
end
local FMc,GMc=0,0
for HMc,IMc in pairs(zMc)do
if IMc>0 then
FMc=FMc+(AMc[HMc]or 0)
GMc=GMc+IMc
end
end
if FMc<=0 or GMc<=0 then
return
end
local JMc=FMc/GMc
bb.lastEff={}
for KMc,LMc in pairs(zMc)do
if LMc>0 and LMc/GMc>0.02 then
local MMc=P.learn[KMc]or{eff=1,n=0,v=3}
if(tonumber(MMc.v)or 0)<3 then
MMc.eff,MMc.v=(tonumber(MMc.eff)or 1)*V.effRescale(KMc),3
end
local NMc=math.max(0.02,0.25*math.sqrt(30/(30+MMc.n)))
local OMc=U.clamp(((AMc[KMc]or 0)/LMc)/JMc,0.2,6)
bb.lastEff[KMc]=math.floor(OMc*1000+0.5)/1000
MMc.eff=MMc.eff+(OMc-MMc.eff)*NMc
MMc.n=MMc.n+1
P.learn[KMc]=MMc
end
end
local PMc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if PMc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==bYd[1816]and P.mapLearn or{}
local QMc=type(P.mapLearn[PMc])==bYd[1816]and P.mapLearn[PMc]or{}
for RMc,SMc in pairs(bb.lastEff)do
local TMc=type(QMc[RMc])==bYd[1816]and QMc[RMc]or{eff=SMc,n=0}
local UMc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(TMc.n)or 0))))
TMc.eff=(tonumber(TMc.n)or 0)==0 and SMc or((tonumber(TMc.eff)or SMc)+(SMc-(tonumber(TMc.eff)or SMc))*UMc)
TMc.n=(tonumber(TMc.n)or 0)+1
QMc[RMc]=TMc
end
QMc._at=os.time()
P.mapLearn[PMc]=QMc
if U.count(P.mapLearn)>80 then
local VMc,WMc
for XMc,YMc in pairs(P.mapLearn)do
if not WMc or(tonumber(YMc._at)or 0)<WMc then
VMc,WMc=XMc,tonumber(YMc._at)or 0
end
end
P.mapLearn[VMc]=nil
end
end
end
