bb.upRate=setmetatable({},{__mode=bYd[2194]})
function bb.refund()
local cSc=N.session()
if not(bb.random and cSc)or bb.spellBusy or bb.roomPlan or not ab.every(bYd[4213],20)then
return
end
local dSc
for eSc,fSc in pairs(cSc.ingame_spells or{})do
if fSc==bYd[4199]then
dSc=eSc
end
end
if not dSc then
return
end
local gSc=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local hSc=bb.bestRate or 0
if gSc or hSc<=0 then
return
end
local iSc=bb.wave()
local jSc=math.max(0,(bb.total or 30)-iSc)
local kSc=bb.mergePlan
local lSc=bb.airLow()
local mSc,nSc,oSc
for pSc,qSc in ipairs(bb.mine)do
local rSc=qSc._stats
local sSc=rSc.id.Value
local tSc=N.Units[sSc]
local uSc=rSc:FindFirstChild(bYd[4195])and tonumber(rSc.total_spent.Value)or 0
if tSc and not tSc.unsellable and uSc>0 and not V.allyBuff(sSc)and not V.idol(sSc)and not(kSc and kSc.id==sSc)then
local vSc,wSc
if V.isFarm(sSc)then
local xSc=rSc:FindFirstChild(bYd[1923])and tonumber(rSc.farm_amount.Value)or 0
local ySc=xSc*jSc
if uSc>ySc*1.2 then
vSc=(uSc-ySc)*hSc
wSc=string.format(bYd[4214],U.fmt(ySc),U.fmt(uSc))
end
elseif iSc>=10 and jSc>2 and uSc>=5000 and(bb.upRate[qSc]or 0)<hSc/3 and bb.progressAt(qSc:GetPivot().Position)<0.8 and not(lSc and bb.canAir(qSc))then
local zSc,ASc=pcall(bb.liveDps,qSc,sSc)
ASc=zSc and ASc or math.huge
if uSc*hSc>3*ASc and ASc<0.1*(bb.teamDps or 0)then
vSc=uSc*hSc-ASc
wSc=string.format(bYd[4215],U.fmt(uSc))
end
end
if vSc and(not nSc or vSc>nSc)then
mSc,nSc,oSc=qSc,vSc,wSc
end
end
end
if not mSc then
return
end
bb.spellBusy=true
task.spawn(function()
local BSc=V.name(mSc._stats.id.Value)
local CSc=F.request(bYd[4206],bYd[4207],dSc,mSc)
task.wait(1.5)
if CSc and(N.session().ingame_spells or{})[dSc]~=bYd[4199]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,bYd[4191],string.format(bYd[4216],BSc,oSc))
F.status(bYd[4085],bYd[4217]..BSc)
else
F.backoff(bYd[4206],15)
F.log(2,bYd[4191],bYd[4218]..BSc)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(DSc,ESc)
local FSc=(ESc.t or 0)-(DSc.t or 0)
if FSc<bb.BASE_WIN-1 then
return false
end
local GSc=((tonumber(DSc.base)or 0)-(tonumber(ESc.base)or 0))/FSc
if GSc<=0 or(tonumber(ESc.base)or 0)<=0 then
return false
end
local HSc=ESc.base/GSc
local ISc,JSc=0,0
local KSc,LSc=DSc.foes or{},ESc.foes or{}
for MSc,NSc in pairs(LSc)do
if NSc.prog>=bb.BASE_END then
ISc=ISc+NSc.hp
local OSc=KSc[MSc]
if OSc then
JSc=JSc+math.max(0,OSc.hp-NSc.hp)
end
end
end
for PSc,QSc in pairs(KSc)do
if QSc.prog>=bb.BASE_END and not LSc[PSc]then
JSc=JSc+QSc.hp
end
end
if ISc<=0 then
return false
end
local RSc=JSc/FSc
local SSc=RSc>0 and ISc/RSc or math.huge
local TSc={baseTime=HSc,loss=GSc,atEnd=ISc,rate=RSc,killTime=SSc}
return HSc<bb.BASE_SOON and SSc>HSc*bb.BASE_MARGIN,TSc
end
