return
end
local jTc=workspace:FindFirstChild(bYd[4231])and workspace._BASES:FindFirstChild(bYd[3790])
local kTc=jTc and jTc:FindFirstChild(bYd[3989])and jTc.base:FindFirstChild(bYd[3990])
