bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(sTc)
local tTc=0
local uTc=U.flat(sTc.pos)
for vTc,wTc in ipairs(bb.mine or{})do
local xTc=wTc:FindFirstChild(bYd[1878])
local yTc=xTc and xTc:FindFirstChild(bYd[2186])
local zTc=xTc and xTc:FindFirstChild(bYd[2060])
if yTc and zTc and not V.isFarm(yTc.Value)and not V.allyBuff(yTc.Value)then
local ATc,BTc=U.flat(wTc:GetPivot().Position),zTc.Value
if(not sTc.fly or bb.canAir(wTc))and(ATc-uTc).Magnitude>BTc then
for CTc,DTc in ipairs(bb.samples or{})do
if DTc.prog>sTc.prog and(U.flat(DTc.pos)-ATc).Magnitude<=BTc then
tTc=tTc+1
break
end
end
end
end
end
return tTc
end
function bb.leakStep(ETc)
if not ETc then
if bb.kind~=bYd[1836]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local FTc=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==bYd[1816]and P.dg.bails or{}
if not ETc and(tonumber(P.dg.bails[FTc])or 0)>=bb.BAIL_MAX then
return
end
local GTc=workspace:FindFirstChild(bYd[4231])and workspace._BASES:FindFirstChild(bYd[3790])
local HTc=GTc and GTc:FindFirstChild(bYd[3989])and GTc.base:FindFirstChild(bYd[3990])
local ITc=HTc and HTc:FindFirstChildOfClass(bYd[2204])
if not ITc or ITc.Health<=0 then
return
end
local JTc=(bb.info and tonumber(bb.info.baseRel))or fb.PRIOR.baseRel
local KTc=U.now()
bb.leakTrack=bb.leakTrack or{}
local LTc=bb.leakTrack
local MTc,NTc={},nil
for OTc,PTc in ipairs(bb.enemies or{})do
if PTc.m then
MTc[PTc.m]=true
local QTc,RTc=tonumber(PTc.hp)or 0,tonumber(PTc.prog)or 0
local STc=LTc[PTc.m]
if not STc then
LTc[PTc.m]={t=KTc,hp=QTc,prog=RTc}
else
if KTc-STc.t>=bb.LEAK_WIN then
STc.pace,STc.net=(RTc-STc.prog)/(KTc-STc.t),(STc.hp-QTc)/(KTc-STc.t)
STc.t,STc.hp,STc.prog=KTc,QTc,RTc
end
if STc.pace and STc.pace>0 and QTc>0 then
local TTc=(1-RTc)/STc.pace
local UTc=math.max(0,STc.net or 0)
local VTc=QTc-UTc*TTc
if VTc>0 and TTc<=bb.LEAK_SOON and TTc>=bb.LEAK_MIN then
local WTc=PTc.m:FindFirstChildOfClass(bYd[2204])
local XTc=ITc.Health/math.max(1,JTc*(WTc and WTc.MaxHealth or QTc))
local YTc=UTc>0 and VTc/UTc or math.huge
if YTc>XTc*bb.LEAK_MARGIN and(TTc<=bb.LEAK_AHEAD or bb.leakAhead(PTc)==0)and(not NTc or TTc<NTc.left)then
NTc={left=TTc,arriving=VTc,net=UTc,baseTime=XTc,hp=QTc}
end
end
end
end
end
end
for ZTc in pairs(LTc)do
if not MTc[ZTc]then
LTc[ZTc]=nil
end
end
if ETc then
return NTc~=nil,NTc
end
if not NTc then
return
end
bb.bailNote(FTc,bYd[4225])
F.log(1,bYd[2464],string.format(bYd[4234],bb.wave(),tonumber(bb.total)or 0,math.floor(NTc.left+0.5),U.fmt(NTc.hp),U.fmt(NTc.arriving),U.fmt(NTc.net),NTc.baseTime))
pcall(F.saveNow)
F.request(bYd[1886],bYd[3832])
end
bb.FOCUS_MAX=8
bb.coverMax=setmetatable({},{__mode=bYd[2194]})
function bb.allPast(_Tc)
local aUc={}
for bUc,cUc in ipairs(bb.mine or{})do
local dUc=cUc._stats
local eUc=dUc.id.Value
if not V.isFarm(eUc)and not V.allyBuff(eUc)and dUc:FindFirstChild(bYd[2060])then
local fUc=tonumber(dUc.range.Value)or 0
local gUc=bb.coverMax[cUc]
if not(gUc and gUc.r==fUc)then
local hUc,iUc=U.flat(cUc:GetPivot().Position),-1
for jUc,kUc in ipairs(bb.samples or{})do
if kUc.prog>iUc and(U.flat(kUc.pos)-hUc).Magnitude<=fUc then
iUc=kUc.prog
end
end
gUc={r=fUc,far=iUc}
bb.coverMax[cUc]=gUc
end
table.insert(aUc,{far=gUc.far,air=bb.canAir(cUc)})
end
end
if#aUc==0 then
return false
end
for lUc,mUc in ipairs(_Tc)do
for nUc,oUc in ipairs(aUc)do
if(not mUc.fly or oUc.air)and oUc.far>=(tonumber(mUc.prog)or 0)then
return false
end
end
end
return true
end
function bb.bossStep()
bb.focus=nil
if bb.random or bb.infinite or not(bb.total and bb.wave()>=bb.total)then
return
end
local pUc=bb.enemies or{}
for qUc,rUc in ipairs(pUc)do
local sUc=rUc.m and rUc.m:FindFirstChildOfClass(bYd[2204])
if sUc and sUc.MaxHealth>((bb.bossTop and bb.bossTop.hp)or 0)then
local tUc=rUc.m:FindFirstChild(bYd[1878])
bb.bossTop={hp=sUc.MaxHealth,id=tUc and tUc:FindFirstChild(bYd[2186])and tUc.id.Value,regen=tUc and tUc:FindFirstChild(bYd[4235])and tUc.Regen.Value}
end
end
if#pUc<=2 and bb.bossTop and not bb.bossSaid then
bb.bossSaid=true
pcall(function()
local uUc=0
if bb.info then
for vUc,wUc in ipairs((fb.wave(bb.info,bb.total)))do
if wUc.boss and wUc.hp>uUc then
uUc=wUc.hp
end
end
end
F.log(1,bYd[2464],string.format(bYd[4236],tostring(bb.bossTop.id),bb.bossTop.hp,tostring(bb.bossTop.regen),uUc))
end)
end
local xUc= #pUc>2 and#pUc<=bb.FOCUS_MAX and bb.allPast(pUc)
if#pUc==0 or(#pUc>2 and not xUc)then
bb.focusTrack=nil
