end
local yUc,zUc=nil,1
for AUc,BUc in ipairs(pUc)do
if not yUc or BUc.hp>yUc.hp then
yUc=BUc
end
zUc=math.min(zUc,BUc.prog)
end
bb.focus={pos=yUc.pos,prog=yUc.prog,fly=yUc.fly,m=yUc.m}
local CUc=U.now()
local DUc=bb.focusTrack
if not DUc or DUc.m~=yUc.m then
