return
end
if CUc-DUc.t>=10 then
DUc.net,DUc.rate=(DUc.hp-yUc.hp)/(CUc-DUc.t),(yUc.prog-DUc.prog)/(CUc-DUc.t)
DUc.t,DUc.hp,DUc.prog=CUc,yUc.hp,yUc.prog
end
