local LUc=KUc._stats
local MUc=LUc.id.Value
local NUc=N.Units[MUc]
if not V.isFarm(MUc)and not V.allyBuff(MUc)and not V.BLESS.by[MUc]and NUc and not NUc.unsellable and LUc:FindFirstChild(bYd[2060])then
local OUc,PUc=U.flat(KUc:GetPivot().Position),LUc.range.Value
