end
end
local XUc=(1-yUc.prog)/DUc.rate
bb.focusLeft,bb.focusInRange=XUc,HUc
local YUc=DUc.net and(DUc.net<=0 or yUc.hp/DUc.net>XUc*0.8)
if YUc and ab.every(bYd[4238],30)then
F.log(1,bYd[2464],string.format(bYd[4239],U.fmt(yUc.hp),U.fmt(DUc.net),math.floor(XUc),HUc))
end
local ZUc=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==bYd[1816]and P.dg.bails or{}
if bb.kind==bYd[1836]and not bb.bailed and O.bailOut~=false and(IUc==0 or XUc<15)and DUc.net and XUc>4 and XUc<60 and(tonumber(P.dg.bails[ZUc])or 0)<bb.BAIL_MAX then
local _Uc=yUc.m and yUc.m:FindFirstChildOfClass(bYd[2204])
local aVc=_Uc and _Uc.MaxHealth or yUc.hp
local bVc=workspace:FindFirstChild(bYd[4231])and workspace._BASES:FindFirstChild(bYd[3790])
local cVc=bVc and bVc:FindFirstChild(bYd[3989])and bVc.base:FindFirstChild(bYd[3990])
local dVc=cVc and cVc:FindFirstChildOfClass(bYd[2204])
local eVc=dVc and dVc.Health or(bb.info and tonumber(bb.info.baseHp))or 100
local fVc=(bb.info and tonumber(bb.info.baseRel))or fb.PRIOR.baseRel
local gVc=yUc.hp-math.max(0,DUc.net)*XUc
local hVc=eVc/math.max(1,fVc*aVc)
local iVc=gVc/math.max(1,DUc.net)
if gVc>0 and(DUc.net<=0 or iVc>hVc*1.3)then
bb.bailNote(ZUc,bYd[2571])
F.log(1,bYd[2464],string.format(bYd[4240],U.fmt(gVc),U.fmt(DUc.net),math.floor(hVc)))
