if FUc[1]and ab.every(bYd[4241],2)then
table.sort(FUc,function(lVc,mVc)
return lVc.spent<mVc.spent
end)
jVc,kVc=FUc[1],HUc>0 and bYd[4242]or bYd[4243]
elseif YUc and GUc[1]and XUc>=30 and ab.every(bYd[4241],8)then
table.sort(GUc,function(nVc,oVc)
return nVc.eta>oVc.eta
end)
if GUc[1].eta>15 then
