function bb.focusSpot(rVc)
local sVc=bb.focus
local tVc=V.range(rVc.u,0)*((bb.info and bb.info.rangeScale)or 1)
local uVc=U.flat(sVc.pos)
local vVc,wVc
local xVc=0
for yVc,zVc in ipairs(bb.cands)do
if(U.flat(zVc)-uVc).Magnitude<=tVc then
local AVc=bb.valid(zVc,rVc.data)
xVc=xVc+1
if xVc%40==0 then
task.wait()
end
if AVc then
local BVc,CVc=0,U.flat(AVc)
for DVc,EVc in ipairs(bb.samples)do
if EVc.prog>=sVc.prog and(U.flat(EVc.pos)-CVc).Magnitude<=tVc then
BVc=BVc+1
end
end
if not wVc or BVc>wVc then
vVc,wVc=AVc,BVc
end
end
end
end
return vVc,wVc or 0
end
function bb.focusGain(FVc)
local GVc=bb.focus
if not GVc then
return 1
end
local HVc=FVc._stats
if not HVc:FindFirstChild(bYd[2060])then
return 1
end
local IVc,JVc=U.flat(FVc:GetPivot().Position),HVc.range.Value
if GVc.fly and not bb.canAir(FVc)then
return 0.02
end
if(IVc-U.flat(GVc.pos)).Magnitude<=JVc then
return 1
end
